CREATE TABLE message_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,template_key text NOT NULL,name text NOT NULL,body text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,template_key));
CREATE TABLE automation_lifecycle_settings(tenant_id uuid PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,confirmation_enabled boolean NOT NULL DEFAULT true,reminder_minutes integer[] NOT NULL DEFAULT ARRAY[1440,120],thank_you_delay_minutes integer NOT NULL DEFAULT 60,review_delay_minutes integer NOT NULL DEFAULT 1440,birthday_enabled boolean NOT NULL DEFAULT true,winback_days integer NOT NULL DEFAULT 30,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_automation_profiles(tenant_id uuid NOT NULL,customer_id uuid NOT NULL,birthday date,automation_opt_out boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,customer_id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id) ON DELETE CASCADE);
